argv:
$ErrorActionPreference='Stop'
try{
 $checks=& gh.exe api --method GET 'repos/foto6/WebAIBridge/check-suites/104386851325/check-runs' 2>$null|ConvertFrom-Json
 foreach($c in @($checks.check_runs)){
  Write-Output ('CHECK='+[string]$c.name)
  Write-Output ('CHECK_ID='+[string]$c.id)
  $a=& gh.exe api --method GET ('repos/foto6/WebAIBridge/check-runs/'+[string]$c.id+'/annotations?per_page=10') 2>$null|ConvertFrom-Json
  foreach($row in @($a)){
   $msg=[string]$row.message
   $msg=$msg.Replace([char]13,' ').Replace([char]10,' ')
   Write-Output ('ANNOTATION_LEVEL='+[string]$row.annotation_level)
   Write-Output ('ANNOTATION_TITLE='+[string]$row.title)
   Write-Output ('ANNOTATION_MESSAGE='+$msg.Substring(0,[Math]::Min($msg.Length,550)))
  }
 }
}catch{Write-Output ('CHECK_ANNOTATION_UNAVAILABLE='+[string]$_.Exception.GetType().Name)}
Write-Output 'NO_RUNNER_MODIFICATION=True'
